import { MakeLogicType, afterMount, connect, kea, path } from 'kea'
import { loaders } from 'kea-loaders'

import { projectLogic } from 'scenes/projectLogic'

import { hogFlowsSendingLimitsRetrieve } from 'products/workflows/frontend/generated/api'
import type { WorkflowSendingLimitsApi } from 'products/workflows/frontend/generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface workflowsSendingLimitsLogicValues {
    currentProjectId: number | null // projectLogic
    sendingLimits: WorkflowSendingLimitsApi | null
    sendingLimitsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface workflowsSendingLimitsLogicActions {
    loadSendingLimits: () => any
    loadSendingLimitsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadSendingLimitsSuccess: (
        sendingLimits: WorkflowSendingLimitsApi | null,
        payload?: any
    ) => {
        sendingLimits: WorkflowSendingLimitsApi | null
        payload?: any
    }
}

export type workflowsSendingLimitsLogicType = MakeLogicType<
    workflowsSendingLimitsLogicValues,
    workflowsSendingLimitsLogicActions
>

export const workflowsSendingLimitsLogic = kea<workflowsSendingLimitsLogicType>([
    path(['products', 'workflows', 'frontend', 'workflowsSendingLimitsLogic']),
    connect(() => ({
        values: [projectLogic, ['currentProjectId']],
    })),
    loaders(({ values }) => ({
        sendingLimits: [
            null as WorkflowSendingLimitsApi | null,
            {
                loadSendingLimits: async () => {
                    if (!values.currentProjectId) {
                        return null
                    }
                    return await hogFlowsSendingLimitsRetrieve(String(values.currentProjectId))
                },
            },
        ],
    })),
    afterMount(({ actions }) => {
        actions.loadSendingLimits()
    }),
])
